<script setup>
import { computed, ref, watch } from 'vue'
import Icon from '../components/Icon.vue'
import StatusBadge from '../components/StatusBadge.vue'
import RunTable from '../components/RunTable.vue'
import TrendChart from '../components/TrendChart.vue'
import { overview, environmentIdsFor } from '../mock/seed.js'
const props = defineProps({ page: String, snapshot: Object, envs: Array, currentUser: Object, canAdmin: Boolean })
const emit = defineEmits(['details', 'run', 'lease', 'borrow', 'maintenance', 'issue', 'device-create', 'device-edit', 'device-remove', 'user-add', 'user-role', 'user-status', 'user-switch'])
const query = ref(''), state = ref('all'), mine = ref(true)
watch(() => props.page, () => { query.value = ''; state.value = 'all' })
const titles = { devices: ['设备资产', '从唯一设备出发，追踪资源关联与真实占用。'], leases: ['借用管理', '统一人工借用、续期、归还与健康复核。'], maintenance: ['环境维护', '记录处理过程，复核通过后再释放资源。'], runs: ['测试执行记录', '关联环境、配置、构建与执行证据，追踪每一次运行。'], quality: ['质量分析', '沿版本与问题记录，查看执行结果和回归线索。'], people: ['人员管理', '配置成员角色；删除类危险操作与人员管理修改仅管理员可执行。'] }
const matches = (row) => Object.values(row).filter(v => typeof v === 'string').join(' ').toLowerCase().includes(query.value.trim().toLowerCase())
const devices = computed(() => props.snapshot.devices.filter(d => matches(d) && (state.value === 'all' || state.value === d.status)))
const leases = computed(() => props.snapshot.leases.filter(l => matches({ ...l, name: environmentIdsFor(l).map(id => `${envName(id)} ${id}`).join(' ') }) && (!mine.value || l.user === props.currentUser?.name) && (state.value === 'all' || state.value === l.status)))
const runs = computed(() => props.snapshot.runs.filter(r => matches(r) && (state.value === 'all' || state.value === r.status)))
const records = computed(() => props.snapshot.maintenance.filter(r => matches({ ...r, name: environmentIdsFor(r).map(id => `${envName(id)} ${id}`).join(' ') }) && (state.value === 'all' || state.value === r.status)))
const users = computed(() => props.snapshot.users.filter(u => matches(u) && (state.value === 'all' || state.value === u.status)))
const stats = overview()
function envName(id) { return props.snapshot.environments.find(e => e.id === id)?.name || id }
function displayDate(date) { return new Date(date).toLocaleString('zh-CN', { timeZone: 'Asia/Shanghai', hour12: false, month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit' }) }
const isSelf = user => user.id === props.currentUser?.id
const stateOptions = computed(() => props.page === 'devices' ? [['available', '空闲'], ['leased', '已借用'], ['running', '执行中'], ['maintenance', '维护中'], ['isolated', '已隔离'], ['cleaning', '待清理'], ['reconciling', '待对账'], ['checking', '待复核']] : props.page === 'leases' ? [['active', '借用中'], ['checking', '待复核'], ['released', '已归还'], ['isolated', '已隔离']] : props.page === 'maintenance' ? [['maintenance', '维护中'], ['isolated', '已隔离'], ['success', '已完成']] : props.page === 'people' ? [['active', '启用'], ['disabled', '停用']] : [['running', '执行中'], ['success', '已完成'], ['failed', '未通过'], ['cleaning', '待清理'], ['reconciling', '待对账']])
</script>
<template>
  <div class="page-heading"><div><div class="eyebrow">{{ page === 'quality' ? 'QUALITY INSIGHTS' : page === 'people' ? 'TEAM & ACCESS' : 'TEST WORKSPACE' }}</div><h1>{{ titles[page][0] }}<span class="demo-tag">{{ page === 'runs' ? '来源见各条记录' : '演示数据' }}</span></h1><p>{{ titles[page][1] }}</p></div><div class="heading-actions"><button v-if="page === 'devices' && canAdmin" class="button primary" @click="emit('device-create')"><Icon name="plus" :size="18" />新增设备</button><button v-if="page === 'leases'" class="button primary" @click="emit('borrow')"><Icon name="plus" :size="18" />申请环境</button><button v-if="page === 'maintenance'" class="button primary" @click="emit('maintenance', null)"><Icon name="plus" :size="18" />创建维护</button><button v-if="page === 'people'" class="button primary" :disabled="!canAdmin" :title="canAdmin ? undefined : '需要管理员权限'" @click="emit('user-add')"><Icon name="plus" :size="18" />新增人员</button></div></div>
  <div v-if="page === 'quality'" class="quality-top"><section class="panel chart-panel"><div class="panel-heading"><h2>版本通过率趋势</h2><span class="subtle-note">OS 24.03 RC2 · 最近 7 天</span></div><TrendChart :points="stats.points" /></section><section class="panel quality-summary"><span class="eyebrow">VERSION QUALITY</span><strong class="mono">{{ stats.rate }}<small>%</small></strong><p>{{ stats.passed }} / {{ stats.total }} 次用例执行通过</p><div class="resource-rule"><Icon name="info" :size="18" /><span>演示结果仅用于浏览与交互，不构成版本发布结论。</span></div></section></div>
  <section class="panel workspace-panel">
    <div v-if="page !== 'quality'" class="workspace-toolbar"><label class="search-field"><Icon name="search" :size="18" /><input v-model="query" :aria-label="`搜索${titles[page][0]}`" placeholder="搜索名称、ID 或关键字" /><button v-if="query" class="icon-button" aria-label="清空搜索" @click="query = ''"><Icon name="close" :size="14" /></button></label><label class="select-label">状态<select v-model="state" aria-label="筛选状态"><option value="all">全部状态</option><option v-for="[value, label] in stateOptions" :key="value" :value="value">{{ label }}</option></select></label><label v-if="page === 'leases'" class="checkbox-label"><input v-model="mine" type="checkbox" />只看我的借用</label><span class="subtle-note toolbar-end">{{ page === 'devices' ? `${devices.length} 台唯一设备` : page === 'people' ? `${users.length} 名人员` : page === 'runs' ? `${runs.length} 条运行` : '浏览器本地演示' }}</span></div>
    <div v-if="page === 'people' && !canAdmin" class="info-banner"><Icon name="shield" :size="18" /><p>当前身份为普通人员：新增环境 / 设备、人员管理操作，以及移出资源池、重置演示数据等删除类危险操作均需要管理员权限。</p></div>
    <div v-if="page === 'devices'" class="table-scroll"><table class="data-table"><thead><tr><th>设备 / ID</th><th>架构 / 类型</th><th>规格</th><th>位置 / IP</th><th>状态</th><th>关联环境</th><th>资源维护</th></tr></thead><tbody><tr v-for="device in devices" :key="device.id"><td><strong>{{ device.name }}</strong><small class="mono">{{ device.id }}</small></td><td>{{ device.arch }}<small>{{ device.type === 'physical' ? '物理机' : '虚拟机' }}</small></td><td>{{ device.cpu || '规格未记录' }}<small>{{ device.memory ? device.memory + ' 内存' : '内存未记录' }}</small></td><td>{{ device.location }}<small class="mono">{{ device.ip }}</small><small v-if="device.type === 'virtual' && device.host" class="mono">宿主机 {{ device.host }}</small></td><td><StatusBadge :status="device.status" :label="device.status === 'available' ? '空闲' : undefined" /></td><td><div class="linked-envs"><button v-for="env in envs.filter(e => e.deviceIds.includes(device.id))" :key="env.id" class="inline-link mono" @click="emit('details', env)">{{ env.id }}<Icon v-if="env.shared" name="link" :size="12" /></button></div></td><td><div class="table-actions"><button class="text-button" @click="emit('device-edit', device)">编辑</button><button class="text-button color-red" :disabled="!canAdmin" :title="canAdmin ? undefined : '需要管理员权限'" @click="emit('device-remove', device)">移出</button></div></td></tr></tbody></table><div v-if="!devices.length" class="empty-state"><Icon name="search" :size="32" /><p>没有匹配的设备</p></div></div>
    <div v-else-if="page === 'leases'" class="table-scroll"><table class="data-table"><thead><tr><th>借用编号 / 环境</th><th>用途</th><th>借用人</th><th>到期时间</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="lease in leases" :key="lease.id"><td><button class="inline-link mono" @click="emit('lease', lease)">{{ lease.id }}</button><div class="borrowed-env-links"><small v-for="id in environmentIdsFor(lease)" :key="id">{{ envName(id) }}</small></div><span v-if="environmentIdsFor(lease).length > 1" class="batch-count">整单 {{ environmentIdsFor(lease).length }} 个环境</span></td><td class="wrap-cell">{{ lease.purpose }}</td><td>{{ lease.user }}</td><td class="mono">{{ displayDate(lease.end) }}</td><td><StatusBadge :status="lease.status" /></td><td><button class="text-button" @click="emit('lease', lease)">{{ lease.status === 'checking' ? '健康复核' : lease.status === 'active' ? '管理借用' : '查看记录' }}</button></td></tr></tbody></table><div v-if="!leases.length" class="empty-state"><Icon name="clipboard" :size="34" /><p>暂无匹配的借用记录</p><button class="button secondary small" @click="emit('borrow')">申请借用环境</button></div></div>
    <div v-else-if="page === 'maintenance'" class="table-scroll"><table class="data-table"><thead><tr><th>维护编号 / 环境</th><th>处理原因</th><th>负责人</th><th>创建时间</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="record in records" :key="record.id"><td><button class="inline-link mono" @click="emit('maintenance', record)">{{ record.id }}</button><small v-for="id in environmentIdsFor(record)" :key="id">{{ envName(id) }}</small></td><td class="wrap-cell">{{ record.reason }}</td><td>{{ record.user }}</td><td class="mono">{{ displayDate(record.date) }}</td><td><StatusBadge :status="record.status" /></td><td><button class="text-button" @click="emit('maintenance', record)">{{ record.status === 'success' ? '查看记录' : '处理与复核' }}</button></td></tr></tbody></table><div v-if="!records.length" class="empty-state"><Icon name="tool" :size="34" /><p>暂无匹配的维护记录</p></div></div>
    <div v-else-if="page === 'people'" class="table-scroll"><table class="data-table"><thead><tr><th>人员</th><th>角色</th><th>状态</th><th>加入时间</th><th>操作</th></tr></thead><tbody><tr v-for="user in users" :key="user.id"><td><strong>{{ user.name }}</strong><small class="mono">{{ user.id }} · {{ user.title }}</small></td><td><span class="badge" :class="user.role === 'admin' ? 'tone-amber' : 'tone-blue'">{{ user.role === 'admin' ? '管理员' : '普通人员' }}</span></td><td><StatusBadge :status="user.status" :label="user.status === 'active' ? '启用' : undefined" /></td><td class="mono">{{ user.joined }}</td><td><div class="table-actions"><button class="text-button" :disabled="!canAdmin || isSelf(user) || user.status !== 'active'" :title="!canAdmin ? '需要管理员权限' : isSelf(user) ? '当前身份即是此人员' : undefined" @click="emit('user-switch', user)">{{ isSelf(user) ? '当前身份' : '以此身份预览' }}</button><button class="text-button" :disabled="!canAdmin || isSelf(user)" :title="!canAdmin ? '需要管理员权限' : isSelf(user) ? '不能调整当前身份自己的角色' : undefined" @click="emit('user-role', user, user.role === 'admin' ? 'member' : 'admin')">{{ user.role === 'admin' ? '设为普通' : '设为管理员' }}</button><button class="text-button" :class="{ 'color-red': user.status === 'active' }" :disabled="!canAdmin || isSelf(user)" :title="!canAdmin ? '需要管理员权限' : isSelf(user) ? '不能停用当前身份自己' : undefined" @click="emit('user-status', user, user.status === 'active' ? 'disabled' : 'active')">{{ user.status === 'active' ? '停用' : '启用' }}</button></div></td></tr></tbody></table><div v-if="!users.length" class="empty-state"><Icon name="user" :size="34" /><p>没有匹配的人员</p></div></div>
    <RunTable v-else-if="page === 'runs'" :runs="runs" @select="emit('run', $event)" />
    <template v-else-if="page === 'quality'"><div class="panel-heading quality-heading"><h2>问题与回归线索</h2><span class="subtle-note">部分问题样例 · 非完整问题清单</span></div><div class="table-scroll"><table class="data-table"><thead><tr><th>问题</th><th>模块</th><th>优先级</th><th>负责人</th><th>状态</th><th>追溯</th></tr></thead><tbody><tr v-for="issue in snapshot.issues" :key="issue.id"><td><button class="inline-link mono" @click="emit('issue', issue)">{{ issue.id }}</button><small>{{ issue.title }}</small></td><td>{{ issue.module }}</td><td><span class="badge" :class="issue.severity === 'P1' ? 'tone-red' : 'tone-amber'">{{ issue.severity }}</span></td><td>{{ issue.owner }}</td><td><StatusBadge :status="issue.status" :label="issue.status === 'success' ? '回归通过' : undefined" /></td><td><button class="text-button" @click="emit('issue', issue)">问题详情<Icon name="chevron" :size="14" /></button></td></tr></tbody></table></div></template>
  </section>
  <div v-if="page !== 'quality'" class="page-footnote"><Icon name="info" :size="15" /><span>{{ page === 'devices' ? '共享设备只计一次；环境状态由所有关联设备共同决定。' : page === 'runs' ? '任务结束后仍需完成清理；状态不明时进入待对账，不能直接释放设备。' : page === 'people' ? '权限变更即时生效；不能修改当前身份自己，至少保留一名启用的管理员。' : '所有操作只修改本浏览器中的 mock 数据，不触发真实设备或外部系统操作。' }}</span></div>
</template>
